<?php

declare(strict_types=1);

namespace VeaIntake\Core;

use RuntimeException;

/**
 * Read-only view of app/data/form-data.json (generated by bin/build-data.php).
 * New, smaller than vea-join's FormData: locals, worksites, states and the
 * "OTHER / NOT LISTED" value, which is stored in the data (docs/PLAN.md section 13).
 *
 * All lookups use exact string matching: callers trim input first.
 */
final class FormData
{
    public const DEFAULT_PATH = __DIR__ . '/../../data/form-data.json';

    /** @var array<string, list<string>> local name => worksites (NOT LISTED last) */
    private array $worksites = [];

    /** @param array<string, mixed> $data */
    private function __construct(private readonly array $data)
    {
        foreach ($data['locals'] as $local) {
            $this->worksites[$local['name']] = $local['worksites'];
        }
    }

    public static function load(string $path = self::DEFAULT_PATH): self
    {
        $raw = @file_get_contents($path);
        if ($raw === false) {
            throw new RuntimeException('form-data.json is not readable');
        }

        return self::fromArray(json_decode($raw, true, 16, JSON_THROW_ON_ERROR));
    }

    /** @param array<string, mixed> $data */
    public static function fromArray(array $data): self
    {
        $ok = is_string($data['version'] ?? null)
            && is_string($data['notListed'] ?? null) && $data['notListed'] !== ''
            && is_array($data['locals'] ?? null) && $data['locals'] !== []
            && is_array($data['states'] ?? null) && $data['states'] !== [];
        if ($ok) {
            foreach ($data['locals'] as $l) {
                if (!is_array($l) || !is_string($l['name'] ?? null) || !is_array($l['worksites'] ?? null)) {
                    $ok = false;
                    break;
                }
            }
        }
        if (!$ok) {
            throw new RuntimeException('form-data.json has an unexpected shape');
        }

        return new self($data);
    }

    public function version(): string
    {
        return $this->data['version'];
    }

    /** "OTHER / NOT LISTED": a choice that requires a typed value. */
    public function notListed(): string
    {
        return $this->data['notListed'];
    }

    /** @return list<string> every local, NOT LISTED last */
    public function localNames(): array
    {
        return array_keys($this->worksites);
    }

    public function hasLocal(string $local): bool
    {
        return isset($this->worksites[$local]);
    }

    /** @return list<string>|null worksites of a local (NOT LISTED last), null for an unknown local */
    public function worksites(string $local): ?array
    {
        return $this->worksites[$local] ?? null;
    }

    public function isWorksite(string $local, string $worksite): bool
    {
        return in_array($worksite, $this->worksites[$local] ?? [], true);
    }

    /** @return list<string> */
    public function states(): array
    {
        return $this->data['states'];
    }

    public function isState(string $value): bool
    {
        return in_array($value, $this->data['states'], true);
    }
}
